import requests

def generate_content(update_content: str, product_name: str, version: str):
    """调用 Dify Workflow API 批量生成多版本内容"""
    # API 地址：使用你的 Dify 实例域名替换 api.dify.ai
    url = "https://api.dify.ai/v1/workflows/run"
    # 请求头：替换为你的应用 API Key
    headers = {
        "Authorization": "Bearer app-xxxxxxxx",  # 必填：应用 API Key
        "Content-Type": "application/json"
    }
    # 请求体：传入 Start 节点定义的三个输入变量
    payload = {
        "inputs": {
            "update_content": update_content,  # 更新日志原文
            "product_name": product_name,      # 产品名称
            "version": version                 # 版本号
        },
        "response_mode": "blocking",  # 阻塞模式，等待完整结果
        "user": "content-team"        # 用户标识，用于日志追踪
    }
    response = requests.post(url, headers=headers, json=payload)
    # 从响应中提取 outputs 字段，包含三个 LLM 节点的生成结果
    return response.json()["data"]["outputs"]

class AgentEvaluator:
    """
    Agent 评测框架
    评估 Agent 在各种任务上的表现
    """
    
    def __init__(self, agent, metrics):
        # 待评测的 Agent
        self.agent = agent
        # 评测指标列表
        self.metrics = metrics
    
    def evaluate(self, test_cases):
        """
        执行评测
        :param test_cases: 测试用例列表
        :return: 评测报告
        """
        results = []
        
        for test_case in test_cases:
            # 执行任务
            result = self.run_single_test(test_case)
            results.append(result)
        
        # 生成评测报告
        report = self.generate_report(results)
        return report
    
    def run_single_test(self, test_case):
        """
        运行单个测试用例
        """
        # 记录开始时间
        start_time = time.time()
        
        # 执行 Agent
        try:
            output = self.agent.run(test_case.input)
            success = self.evaluate_output(output, test_case.expected)
            error = None
        except Exception as e:
            output = None
            success = False
            error = str(e)
        
        # 记录结束时间
        end_time = time.time()
        
        return TestResult(
            test_case=test_case,
            output=output,
            success=success,
            error=error,
            duration=end_time - start_time,
            token_count=self.count_tokens(output)
        )
    
    def evaluate_output(self, output, expected):
        """评估输出是否符合预期"""
        for metric in self.metrics:
            if not metric.evaluate(output, expected):
                return False
        return True
    
    def generate_report(self, results):
        """生成评测报告"""
        total = len(results)
        passed = sum(1 for r in results if r.success)
        
        # 计算各项指标
        avg_duration = sum(r.duration for r in results) / total
        avg_tokens = sum(r.token_count for r in results) / total
        
        # 按测试类型分组统计
        by_category = {}
        for r in results:
            category = r.test_case.category
            if category not in by_category:
                by_category[category] = {"total": 0, "passed": 0}
            by_category[category]["total"] += 1
            if r.success:
                by_category[category]["passed"] += 1
        
        return EvaluationReport(
            total=total,
            passed=passed,
            pass_rate=passed / total,
            avg_duration=avg_duration,
            avg_tokens=avg_tokens,
            by_category=by_category,
            results=results
        )


class TestCase:
    """测试用例"""
    
    def __init__(self, input, expected, category="general", metadata=None):
        # 输入
        self.input = input
        # 预期输出或评估标准
        self.expected = expected
        # 类别
        self.category = category
        # 额外元数据
        self.metadata = metadata or {}


class TestResult:
    """测试结果"""
    
    def __init__(self, test_case, output, success, error, duration, token_count):
        self.test_case = test_case
        self.output = output
        self.success = success
        self.error = error
        self.duration = duration
        self.token_count = token_count


class Metric:
    """评测指标基类"""
    
    def evaluate(self, output, expected):
        raise NotImplementedError


class ExactMatchMetric(Metric):
    """精确匹配指标"""
    
    def evaluate(self, output, expected):
        return output.strip() == expected.strip()


class ContainsMetric(Metric):
    """包含关键词指标"""
    
    def evaluate(self, output, expected):
        if isinstance(expected, list):
            return all(keyword in output for keyword in expected)
        return expected in output


class SemanticSimilarityMetric(Metric):
    """语义相似度指标"""
    
    def __init__(self, threshold=0.8):
        self.threshold = threshold
    
    def evaluate(self, output, expected):
        similarity = self.compute_similarity(output, expected)
        return similarity >= self.threshold
    
    def compute_similarity(self, text1, text2):
        """计算两个文本的语义相似度"""
        # 使用嵌入模型计算余弦相似度
        embedding1 = self.embedder.embed([text1])[0]
        embedding2 = self.embedder.embed([text2])[0]
        return cosine_similarity(embedding1, embedding2)

